//! Differential-vector parity tests for `src/js_number/`.
//!
//! Vectors are generated by `scripts/rust-parity/dump-js-number.ts` (run via
//! `pnpm exec tsx --tsconfig tsconfig.node.json scripts/rust-parity/dump-js-number.ts`)
//! against the real V8/Node runtime and the real production
//! `canonicalLinearMetric`/`canonicalAreaMetric` functions
//! (`src/workers/algorithm/irregular/intrinsicStrictDecoder.ts:1692-1698`),
//! and committed at `tests/vectors/js-number.json`. Every value in this file
//! is loaded at compile time via `include_str!`, so the test does not depend
//! on the process's working directory.
//!
//! f64 inputs/outputs are encoded as 16-hex-character IEEE-754 bit-pattern
//! strings (not JSON numbers), which sidesteps both JSON's inability to
//! represent `NaN`/`Infinity` and any risk of lossy decimal round-tripping —
//! every comparison below is bit-exact via `f64::to_bits()`, per the
//! migration prompt's R14/R7 requirements. Vectors whose expected result is
//! `NaN` carry an explicit `expectedIsNaN` flag and are checked with
//! `f64::is_nan()` instead of exact-bits equality, since IEEE 754 does not
//! mandate a portable NaN payload between V8 and Rust (only that the
//! exponent/quiet bits are set) — every other primitive here (round, trunc,
//! sign, floor, ceil, max, min, the signed-zero fold) is checked bit-exact,
//! including distinguishing `+0.0` from `-0.0`.

use irregular_nesting_native::js_number::js_math::{
    ceil, floor, max, max_all, min, min_all, round, sign, trunc,
};
use irregular_nesting_native::js_number::{
    cmp_js_code_units, fold_negative_zero, is_safe_integer, number_to_js_string,
};
use serde::Deserialize;
use std::cmp::Ordering;

const VECTORS_JSON: &str = include_str!("vectors/js-number.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Meta {
    area: String,
    generating_commit: String,
    #[allow(dead_code)]
    generated_at: String,
    #[allow(dead_code)]
    node_version: String,
    #[allow(dead_code)]
    description: String,
}

#[derive(Deserialize)]
struct StringVector {
    bits: String,
    expected: String,
}

#[derive(Deserialize)]
struct BoolVector {
    bits: String,
    expected: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct F64Vector {
    bits: String,
    expected_bits: String,
    #[serde(rename = "expectedIsNaN")]
    expected_is_nan: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct PairVector {
    a_bits: String,
    b_bits: String,
    expected_bits: String,
    #[serde(rename = "expectedIsNaN")]
    expected_is_nan: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AllVector {
    values_bits: Vec<String>,
    expected_bits: String,
    #[serde(rename = "expectedIsNaN")]
    expected_is_nan: bool,
}

#[derive(Deserialize)]
struct StrCmpVector {
    first: String,
    second: String,
    expected: i32,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct VectorFile {
    meta: Meta,
    number_to_string: Vec<StringVector>,
    is_safe_integer: Vec<BoolVector>,
    fold_negative_zero: Vec<F64Vector>,
    math_round: Vec<F64Vector>,
    math_trunc: Vec<F64Vector>,
    math_sign: Vec<F64Vector>,
    math_floor: Vec<F64Vector>,
    math_ceil: Vec<F64Vector>,
    math_max_pairs: Vec<PairVector>,
    math_min_pairs: Vec<PairVector>,
    math_max_all: Vec<AllVector>,
    math_min_all: Vec<AllVector>,
    canonical_linear_metric: Vec<F64Vector>,
    canonical_area_metric: Vec<F64Vector>,
    cmp_js_code_units: Vec<StrCmpVector>,
}

fn load_vectors() -> VectorFile {
    serde_json::from_str(VECTORS_JSON).expect("tests/vectors/js-number.json must parse")
}

fn from_bits_hex(hex: &str) -> f64 {
    let bits = u64::from_str_radix(hex, 16).unwrap_or_else(|err| {
        panic!("vector bit pattern {hex:?} is not valid hex: {err}");
    });
    f64::from_bits(bits)
}

/// Asserts `actual` matches an expected `(bits, isNaN)` pair: bit-exact
/// (including zero sign) when finite, `is_nan()`-only when the oracle
/// produced `NaN` (see module doc for why NaN payload bits are excluded from
/// the comparison). Takes the expected fields directly (rather than an
/// `F64Vector`/`PairVector`/`AllVector` reference) so every vector shape in
/// this file can share one comparison without an artificial common trait or
/// struct-adapter indirection.
fn assert_bits_or_nan(actual: f64, expected_bits_hex: &str, expected_is_nan: bool, context: &str) {
    if expected_is_nan {
        assert!(
            actual.is_nan(),
            "{context}: expected NaN, got {actual:?} (bits {:016x})",
            actual.to_bits()
        );
        return;
    }
    let expected = from_bits_hex(expected_bits_hex);
    assert_eq!(
        actual.to_bits(),
        expected.to_bits(),
        "{context}: expected {expected:?} (bits {:016x}), got {actual:?} (bits {:016x})",
        expected.to_bits(),
        actual.to_bits()
    );
}

#[test]
fn vector_file_header_records_generating_commit() {
    let file = load_vectors();
    assert_eq!(file.meta.area, "js-number");
    assert_eq!(
        file.meta.generating_commit.len(),
        40,
        "generating_commit must be a full git SHA-1 hex string"
    );
    assert!(
        file.meta
            .generating_commit
            .chars()
            .all(|c| c.is_ascii_hexdigit()),
        "generating_commit must be hex: {}",
        file.meta.generating_commit
    );
}

#[test]
fn number_to_js_string_matches_v8() {
    let file = load_vectors();
    assert!(file.number_to_string.len() >= 500);
    for vector in &file.number_to_string {
        let input = from_bits_hex(&vector.bits);
        assert_eq!(
            number_to_js_string(input),
            vector.expected,
            "input bits {} ({input:?})",
            vector.bits
        );
    }
}

