#[test]
fn fold_negative_zero_matches_v8_ternary_idiom() {
    let file = load_vectors();
    for vector in &file.fold_negative_zero {
        let input = from_bits_hex(&vector.bits);
        assert_bits_or_nan(
            fold_negative_zero(input),
            &vector.expected_bits,
            vector.expected_is_nan,
            "fold_negative_zero",
        );
    }
}

