#[test]
fn math_max_all_matches_v8() {
    let file = load_vectors();
    for vector in &file.math_max_all {
        let values: Vec<f64> = vector
            .values_bits
            .iter()
            .map(|b| from_bits_hex(b))
            .collect();
        assert_bits_or_nan(
            max_all(&values),
            &vector.expected_bits,
            vector.expected_is_nan,
            "max_all",
        );
    }
}

