/// Reproduces `canonicalLinearMetric`
/// (`src/workers/algorithm/irregular/intrinsicStrictDecoder.ts:1692-1693`:
/// `Math.round(valueMm * 1_000)`) using only this module's own `round`
/// primitive, to differentially validate `round` against a real production
/// call site rather than only against directly-invoked `Math.round`. This is
/// deliberately not exported from `js_number` — ownership of a first-class
/// Rust `canonical_linear_metric` belongs to whichever module ports
/// `intrinsicStrictDecoder.ts`.
fn canonical_linear_metric(value_mm: f64) -> f64 {
    round(value_mm * 1_000.0)
}

/// Reproduces `canonicalAreaMetric`
/// (`src/workers/algorithm/irregular/intrinsicStrictDecoder.ts:1697-1698`:
/// `Math.round(valueMm2 * 1_000_000)`). See [`canonical_linear_metric`].
fn canonical_area_metric(value_mm2: f64) -> f64 {
    round(value_mm2 * 1_000_000.0)
}

#[test]
fn canonical_linear_metric_matches_real_production_function() {
    let file = load_vectors();
    assert!(file.canonical_linear_metric.len() >= 100);
    for vector in &file.canonical_linear_metric {
        let input = from_bits_hex(&vector.bits);
        assert_bits_or_nan(
            canonical_linear_metric(input),
            &vector.expected_bits,
            vector.expected_is_nan,
            "canonical_linear_metric",
        );
    }
}

