#[test]
fn cmp_js_code_units_matches_v8_over_fixture_id_alphabet() {
    let file = load_vectors();
    assert!(file.cmp_js_code_units.len() >= 200);
    for vector in &file.cmp_js_code_units {
        let actual = match cmp_js_code_units(&vector.first, &vector.second) {
            Ordering::Less => -1,
            Ordering::Equal => 0,
            Ordering::Greater => 1,
        };
        assert_eq!(
            actual, vector.expected,
            "cmp_js_code_units({:?}, {:?})",
            vector.first, vector.second
        );
    }
}
